"""Edge-case tests for PYTHON DIAGNOSTICS step-4 cohesion campaign — generated by bug-hunter agent.

Targets the derivations the campaign introduced:

1. ``FerrumVisualizer.score()`` promoted to the base class with a
   ``callable(getattr(model, "score", None))`` guard and a ``0.0`` fallback,
   and ``has_score`` derived as a property mirroring that guard
   (``src/ferrum/diagnostics/visualizers/_base.py`` lines 57-68, 135-164).
2. ``compare=`` / ``random_state`` uniform across the model-diagnostic family.
   Most diagnostics now render small multiples on ``compare=``; the sweep-based
   clustering charts (no per-model source) keep a documented ``ValueError`` via
   the ``_reject_compare`` guard
   (``src/ferrum/plots/_helpers.py`` ``_reject_compare`` / ``_resolve_source``).
3. First-param canonicalization via ``_resolve_first_param`` + ``_UNSET``
   (``src/ferrum/plots/_helpers.py`` lines 360-392).

Every test names the exact code path it exercises and asserts a specific
outcome (a metric value, an exception, or the ``has_score`` boolean) — not
"no crash".  Models are tiny sklearn estimators fit on synthetic numpy arrays
so the suite stays fast.
"""

from __future__ import annotations

import warnings

import numpy as np
import pytest

import ferrum


# ---------------------------------------------------------------------------
# Tiny synthetic fixtures (no skops; models fit in <50 rows).
# ---------------------------------------------------------------------------


@pytest.fixture(scope="module")
def binary():
    """Tiny binary-classification problem + a fitted LogisticRegression."""
    from sklearn.linear_model import LogisticRegression

    rng = np.random.RandomState(0)
    X = rng.randn(40, 3)
    y = (X[:, 0] + 0.3 * rng.randn(40) > 0).astype(int)
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        model = LogisticRegression().fit(X, y)
    return model, X, y


@pytest.fixture(scope="module")
def regression():
    """Tiny regression problem + a fitted Ridge."""
    from sklearn.linear_model import Ridge

    rng = np.random.RandomState(1)
    X = rng.randn(40, 3)
    y = X[:, 0] * 2.0 - X[:, 1] + 0.1 * rng.randn(40)
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        model = Ridge().fit(X, y)
    return model, X, y


# ---------------------------------------------------------------------------
# Synthetic non-estimator / partial-protocol "models" — these probe the
# base-class guard directly without any sklearn dependency.
# ---------------------------------------------------------------------------


class _NoScoreModel:
    """Exposes ``predict`` but NOT ``score`` (e.g. a transformer-only object)."""

    def predict(self, X):  # noqa: N803
        return np.zeros(len(X))


class _NonCallableScore:
    """Has a ``score`` *attribute* that is not callable (a data field)."""

    score = 0.75  # a float, NOT a method

    def predict(self, X):  # noqa: N803
        return np.zeros(len(X))


class _ProbaNoScore:
    """Exposes ``predict`` + ``predict_proba`` but NO ``score`` method.

    The crucial adversarial shape for ROCVisualizer: its overridden score()
    returns a real roc_auc, but the *base* has_score guard only checks
    ``model.score``.
    """

    classes_ = np.array([0, 1])

    def predict(self, X):  # noqa: N803
        return np.zeros(len(X), dtype=int)

    def predict_proba(self, X):  # noqa: N803
        n = len(X)
        p = np.linspace(0.05, 0.95, n)
        return np.column_stack([1.0 - p, p])


# ===========================================================================
# Category: base-class score()/has_score derivation (Null/degenerate model)
# ===========================================================================


def test_has_score_true_for_model_with_callable_score(regression):
    """has_score must be True when the wrapped model exposes a callable .score.

    Exercises `_base.has_score` (line 68) — the ``callable(getattr(...))`` guard
    against a real Ridge regressor.
    """
    model, X, y = regression
    viz = ferrum.ResidualsVisualizer(model).fit(X, y)
    assert viz.has_score is True


def test_score_returns_exact_estimator_metric(regression):
    """Base score() must return float(model.score(X, y)) bit-for-bit.

    Exercises `_base.score` (line 162-164): a Ridge regressor's .score is
    r2_score, so the visualizer's score must equal it exactly.
    """
    model, X, y = regression
    viz = ferrum.ResidualsVisualizer(model).fit(X, y)
    assert viz.score(X, y) == pytest.approx(float(model.score(X, y)))


def test_has_score_false_and_score_zero_for_no_score_model():
    """A model with predict but no .score: has_score False, score()==0.0 fallback.

    Exercises both `_base.has_score` and `_base.score` fallback branch (line 164).
    """
    viz = ferrum.ResidualsVisualizer(_NoScoreModel())
    assert viz.has_score is False
    assert viz.score(np.zeros((3, 2)), np.zeros(3)) == 0.0


def test_has_score_false_for_non_callable_score_attribute():
    """A non-callable ``score`` attribute must NOT count as a scorer.

    Exercises the ``callable(...)`` part of the guard (line 68 / 162): a plain
    float ``score`` field must be rejected so score() falls through to 0.0.
    """
    viz = ferrum.ResidualsVisualizer(_NonCallableScore())
    assert viz.has_score is False
    assert viz.score(np.zeros((3, 2)), np.zeros(3)) == 0.0


def test_has_score_false_for_model_none():
    """model=None (genuinely no-model) yields has_score False and score() 0.0.

    Exercises `_base.has_score` with ``self.model is None`` —
    ``getattr(None, "score", None)`` is None, not callable.
    """
    viz = ferrum.ResidualsVisualizer(None)
    assert viz.has_score is False
    assert viz.score(np.zeros((3, 2)), np.zeros(3)) == 0.0


def test_has_score_iff_score_nonfallback_invariant_base_family(regression):
    """The documented invariant: has_score True <=> score() != 0.0 fallback.

    For base-delegating visualizers the invariant must hold. Ridge's r2 on its
    own training data is > 0, so has_score True and score() != 0.0.
    Exercises the "two can never drift" guarantee in the `_base.has_score`
    docstring for the *non-overriding* family members.
    """
    model, X, y = regression
    for cls in (
        ferrum.ResidualsVisualizer,
        ferrum.PredictionErrorVisualizer,
    ):
        viz = cls(model).fit(X, y)
        assert viz.has_score is True
        assert viz.score(X, y) != 0.0


def test_roc_has_score_matches_overridden_score_for_proba_only_model():
    """has_score must agree with the OVERRIDDEN score() for ROCVisualizer.

    ROCVisualizer.score computes roc_auc_score from predict_proba, NOT from
    model.score. A model exposing predict_proba but no .score therefore returns
    a real, non-fallback metric, so ``ROCVisualizer.has_score`` mirrors the same
    ``predict_proba``-or-``.score`` condition (`_classification.py`) and reports
    True. The docstring promise — has_score is True "exactly when" score()
    returns a real metric — holds for this input.
    """
    model = _ProbaNoScore()
    X = np.random.RandomState(0).randn(10, 2)
    y = np.array([0, 0, 1, 0, 1, 1, 0, 1, 1, 1])
    viz = ferrum.ROCVisualizer(model)
    real_metric = viz.score(X, y)
    assert real_metric != 0.0  # the override produced a real AUC
    # The invariant the docstring guarantees:
    assert viz.has_score is True


def test_roc_score_override_returns_auc_not_accuracy(binary):
    """ROCVisualizer.score must return roc_auc_score, distinct from accuracy.

    Exercises `_classification.py` line 91-98: with predict_proba present the
    override returns the binary roc_auc (proba[:, 1]), NOT model.score accuracy.
    """
    from sklearn.metrics import roc_auc_score

    model, X, y = binary
    viz = ferrum.ROCVisualizer(model)
    expected = float(roc_auc_score(y, model.predict_proba(X)[:, 1]))
    assert viz.score(X, y) == pytest.approx(expected)


# ===========================================================================
# Category: CalibrationVisualizer multi-model first-param (composition corner)
# ===========================================================================


def test_calibration_dict_positional_has_score_reflects_scoreable_models(binary):
    """Dict-positional CalibrationVisualizer is a multi-model overlay.

    A dict-of-models overlay has no single well-defined ``.score``, so the
    honest contract (`_classification.py` ``CalibrationVisualizer.has_score`` /
    ``score``) reports ``has_score=False`` and ``score()=0.0`` — never the
    silent ``models[0]`` collapse, and the two stay mutually consistent.
    """
    model, X, y = binary
    viz = ferrum.CalibrationVisualizer({"a": model, "b": model})
    assert viz.has_score is False
    assert viz.score(X, y) == 0.0


def test_calibration_two_positional_score_is_not_silently_first_model_only(binary):
    """Two-positional CalibrationVisualizer must not silently score only m_a.

    A two-model overlay has no single metric, so ``score()`` returns the
    documented ``0.0`` no-single-score fallback (consistent with
    ``has_score=False``) rather than silently collapsing to ``m_a``'s score.
    """
    from sklearn.dummy import DummyClassifier

    model, X, y = binary
    alt = DummyClassifier(strategy="constant", constant=0).fit(X, y)
    viz = ferrum.CalibrationVisualizer(model, alt)
    # A multi-model overlay reports the honest no-single-score fallback, not
    # the silent first-model-only metric.
    assert viz.has_score is False
    assert viz.score(X, y) == 0.0
    # And critically, score() is NOT silently the first model's metric.
    assert viz.score(X, y) != pytest.approx(float(model.score(X, y)))


