def test_compare_dict_supported_path_overlays_two_models(binary):
    """compare= on a SUPPORTED chart (roc_chart) overlays two model series.

    Exercises `_resolve_source` compare branch (`_helpers.py` 460-471): the
    base model becomes label "base"; compare keys add the rest. ROC's legend
    builder appends the per-series AUC to the ``model`` value, so we assert the
    two distinct series each carry a base/alt prefix rather than exact labels.
    """
    model, X, y = binary
    chart = ferrum.roc_chart(model, X, y, compare={"alt": model})
    data = chart._data
    assert data is not None and "model" in data.columns
    series = sorted(data["model"].unique().to_list())
    assert len(series) == 2
    assert any(s.startswith("base") for s in series)
    assert any(s.startswith("alt") for s in series)


def test_compare_single_model_dict_still_carries_model_column(regression):
    """compare={'alt': m} (one extra model) yields exactly two series.

    Exercises `_resolve_source` compare branch with a one-entry dict on the
    SUPPORTED prediction_error_chart path.
    """
    model, X, y = regression
    chart = ferrum.prediction_error_chart(model, X, y, compare={"alt": model})
    data = chart._data
    assert data is not None and "model" in data.columns
    assert sorted(data["model"].unique().to_list()) == ["alt", "base"]


def test_compare_on_excluded_chart_raises_documented_valueerror(regression):
    """An EXCLUDED chart must raise ValueError, never silently drop compare=.

    Exercises `_reject_compare` (`_helpers.py` 171-181) via the sweep-based
    ``cluster_diagnostics`` (no per-model source, so it stays excluded): the
    message must name the chart and carry a documented reason.
    """
    _, X, _ = regression
    with pytest.raises(ValueError, match="compare= is not supported for cluster_diagnostics"):
        ferrum.cluster_diagnostics(X, ks=[2, 3, 4], compare={"alt": X})


def test_compare_on_excluded_chart_message_carries_reason(regression):
    """The rejection message includes the *why*, not just the chart name.

    Exercises the ``reason`` arg threaded into `_reject_compare`.
    """
    _, X, _ = regression
    with pytest.raises(ValueError) as exc:
        ferrum.cluster_diagnostics(X, ks=[2, 3, 4], compare={"alt": X})
    msg = str(exc.value)
    prefix = "compare= is not supported for cluster_diagnostics:"
    assert msg.startswith(prefix)
    assert msg[len(prefix) :].strip()


