def test_compare_none_byte_identical_to_omitting_kwarg(regression):
    """compare=None must be byte-identical to omitting the kwarg.

    Exercises that the default path is untouched — `_resolve_source` only
    enters the compare branch when ``compare is not None``.
    """
    model, X, y = regression
    with_kwarg = ferrum.prediction_error_chart(model, X, y, compare=None).to_svg()
    without = ferrum.prediction_error_chart(model, X, y).to_svg()
    assert with_kwarg == without


def test_compare_random_state_forwarded_through_compare_source(binary):
    """random_state passed alongside compare= reaches each wrapped ModelSource.

    Exercises `_resolve_source` (`_helpers.py` 466-470): random_state is
    forwarded to ModelSource.compare. Two builds with the same seed must be
    byte-identical (deterministic).
    """
    model, X, y = binary
    a = ferrum.roc_chart(model, X, y, compare={"alt": model}, random_state=7).to_svg()
    b = ferrum.roc_chart(model, X, y, compare={"alt": model}, random_state=7).to_svg()
    assert a == b


# BUG?: compare={} (empty dict) is "not None", so on a SUPPORTED chart it
# routes through the compare path producing a spurious single-"base" model
# column instead of behaving like compare=None.  Pin the current contract so a
# future change to treat {} as None is caught.
def test_compare_empty_dict_on_supported_chart_produces_base_only_series(regression):
    """compare={} on a supported chart yields a lone 'base' model series.

    Exercises `_resolve_source` (`_helpers.py` 465): models = {"base": m, **{}}
    = {"base": m}. The empty comparison is silently promoted to a one-model
    "comparison" rather than collapsing to the no-compare default. This pins
    the (surprising) current behaviour.
    """
    model, X, y = regression
    chart = ferrum.prediction_error_chart(model, X, y, compare={})
    data = chart._data
    assert data is not None and "model" in data.columns
    assert data["model"].unique().to_list() == ["base"]


