# ===========================================================================
# Family-wide invariant: has_score <=> score() returns a real (non-0.0) metric
# ===========================================================================
#
# The durable guard the `_base.has_score` docstring promises: for EVERY
# concrete visualizer, `has_score` is True exactly when `score(X, y)` returns a
# real metric (not the 0.0 fallback). `has_score` / `score()` are pure query
# methods of the wrapped model(s) — independent of `.fit()` — so the invariant
# is checked at construction time across every model shape without needing each
# visualizer's heavyweight derived-data compute.


def _build_visualizer(cls, model):
    """Construct a concrete visualizer for ``model`` with minimal required args.

    Returns the instance, or ``None`` to skip classes whose constructor never
    takes a positional ``model`` (the genuine no-model visualizers, covered by
    their own dedicated tests).
    """
    name = cls.__name__
    # No-model visualizers take no positional ``model`` at all — they are
    # always has_score=False / score()=0.0, covered by the dedicated tests.
    if name in {
        "Rank1DVisualizer",
        "Rank2DVisualizer",
        "ParallelCoordinatesVisualizer",
        "ClassBalanceVisualizer",
        "ElbowVisualizer",  # takes a model *class*; always wraps model=None
    }:
        return None
    # Constructors needing extra required args beyond ``model``.
    if name == "ValidationCurveVisualizer":
        return cls(model, "C", np.array([0.1, 1.0]))
    if name == "AlphaSelectionVisualizer":
        return cls(model, np.array([0.1, 1.0]))
    if name == "SHAPWaterfallVisualizer":
        return cls(model, sample_idx=0)
    if name == "SHAPVisualizer":
        # Deprecated shim — constructing it warns; the dedicated SHAP sibling
        # classes exercise the same has_score/score path.
        return None
    return cls(model)


def _concrete_visualizers():
    """Every concrete (non-base) visualizer class exported by the family."""
    from ferrum.diagnostics import visualizers as _viz

    return [getattr(_viz, name) for name in _viz.__all__ if name != "FerrumVisualizer"]


@pytest.mark.parametrize("cls", _concrete_visualizers(), ids=lambda c: c.__name__)
def test_has_score_iff_score_is_real_metric_family_wide(cls):
    """For every model-backed visualizer, has_score <=> score() is non-fallback.

    Covers the model shapes the docstring's "can never drift" promise spans:
    a proba-only model (the ROC override), a no-.score model, a non-callable
    .score attribute, and no model. For every one of these shapes ``score()``
    is well-defined without a real estimator metric, so the test asserts the
    exact invariant: ``has_score`` is True iff ``score()`` returns a real
    metric (not the 0.0 fallback). The model-with-real-.score shape needs a
    fitted estimator + matching data, so it is exercised by the per-class
    fit-based tests above; here we pin the no-drift behavior at the boundary
    cases where every visualizer's score() must agree with has_score.
    """
    shapes = [
        # proba-only model: no .score, predict_proba present. ROC scores this
        # to a real AUC (has_score True); every other visualizer falls through
        # to the 0.0 fallback (has_score False). Either way the two must agree.
        (
            _ProbaNoScore(),
            np.random.RandomState(0).randn(10, 2),
            np.array([0, 0, 1, 0, 1, 1, 0, 1, 1, 1]),
        ),
        # predict-only model: neither .score nor predict_proba → always fallback
        (_NoScoreModel(), np.zeros((10, 2)), np.zeros(10, dtype=int)),
        # non-callable .score attribute: must not count as scoreable
        (_NonCallableScore(), np.zeros((10, 2)), np.zeros(10, dtype=int)),
        # no model at all
        (None, np.zeros((10, 2)), np.zeros(10, dtype=int)),
    ]

    for model, X, y in shapes:
        viz = _build_visualizer(cls, model)
        if viz is None:
            continue
        # The invariant in one line: has_score is True exactly when score()
        # returns a real metric rather than the 0.0 no-score fallback.
        is_real_metric = viz.score(X, y) != 0.0
        assert viz.has_score == is_real_metric, (
            f"{cls.__name__} with model={type(model).__name__}: "
            f"has_score={viz.has_score} but score()-is-real-metric={is_real_metric}"
        )


def test_no_model_visualizers_uniformly_unscoreable(regression):
    """The four genuine no-model visualizers all report has_score False / 0.0.

    Rank1D / Rank2D / ParallelCoordinates / ClassBalance never wrap a model, so
    the invariant pins them to the no-score fallback uniformly (no sibling left
    drifting toward a misleading has_score True).
    """
    _, X, y = regression
    for viz in (
        ferrum.Rank1DVisualizer(algorithm="variance"),
        ferrum.Rank2DVisualizer(),
        ferrum.ParallelCoordinatesVisualizer(),
        ferrum.ClassBalanceVisualizer(),
    ):
        assert viz.has_score is False
        assert viz.score(X, y) == 0.0


def test_elbow_visualizer_unscoreable():
    """ElbowVisualizer wraps model=None (a model *class*, not an instance).

    Its score is the per-k sweep, not a single estimator metric, so has_score
    is False and score() is the 0.0 fallback — consistent with the invariant.
    """
    from sklearn.cluster import KMeans

    viz = ferrum.ElbowVisualizer(KMeans, ks=[2, 3])
    assert viz.has_score is False
    assert viz.score(np.zeros((4, 2)), None) == 0.0
